                        # Mark this function call as streaming.
                        state.function_call_streaming[tc_delta.index] = True

                        # Send initial function call added event
                        yield ResponseOutputItemAddedEvent(
                            item=cls._function_call_item(
                                state,
                                function_call,
                                arguments="",
